code.python:
from dataclasses import dataclass

@dataclass
class Estudiante:
    nombre: str

@dataclass
class Visitante:
    pass

Usuario = Estudiante | Visitante    # unión cerrada (solo la comprueba el verificador de tipos)

def describir(u: Usuario) -> str:
    match u:
        case Estudiante(nombre=n):
            return f"Estudiante {n}"
        case Visitante():
            return "Visitante"

uso.java:
public static void main(String[] args) {
    System.out.println(describir(new Estudiante("Ana")));
    System.out.println(describir(new Visitante()));
}

